mapper.select:
select rental_pty_id
from tenancy
where mbr_cd = #{mbrCd}

select bldg_id, bldg_nm
from building
where rental_pty_id = #{rentalPtyId}

select unit_id, unit_room
from unit
where bldg_id = #{bldgId}
and rental_pty_id = #{rentalPtyId}

  select count(*)
  from charge_bill a
  inner join unit b on (a.unit_id = b.unit_id)
  inner join building c on (b.bldg_id = c.bldg_id)
  inner join member d on (b.mbr_cd = d.mbr_cd)
  where a.rental_pty_id = #{rentalPtyId}

    AND b.bldg_id = #{bldgId}


    AND b.unit_room = #{unitRoom}


    AND a.chgbill_status = #{chgbillStatus}


    AND a.chgbill_charge_month = #{chgbillChargeMonth}


	 AND TO_DATE(a.chgbill_due_date, 'yyyy-mm-dd')
	     BETWEEN #{chgbillDueStartDate} AND #{chgbillDueEndDate}


SELECT * FROM (
  SELECT inner_query.*, ROWNUM rn
  FROM (
    SELECT a.*, c.BLDG_NM, b.UNIT_FLR_NO, b.UNIT_ROOM, d.MBR_NM
    FROM charge_bill a
    INNER JOIN unit b ON (a.unit_id = b.unit_id)
    INNER JOIN building c ON (b.bldg_id = c.bldg_id)
    INNER JOIN member d ON (b.mbr_cd = d.mbr_cd)
    WHERE 1=1



    AND a.rental_pty_id = #{cbh.rentalPtyId}




    AND b.bldg_id = #{cbh.bldgId}




    AND b.unit_room = #{cbh.unitRoom}




    AND a.chgbill_status = #{cbh.chgbillStatus}




    AND a.chgbill_charge_month = #{cbh.chgbillChargeMonth}




    AND TO_DATE(a.chgbill_due_date, 'yyyy-mm-dd')
        BETWEEN #{cbh.chgbillDueStartDate} AND #{cbh.chgbillDueEndDate}



    ORDER BY a.chgbill_due_date DESC
  ) inner_query
  WHERE ROWNUM <= #{endRow}
)
WHERE rn >= #{startRow}

SELECT DUM_COMP ,TOTAL_ENERGY_CHARGE_AMT, TOTAL_ENERGY_USAGE_QTY
FROM HOUSEHOLD_ENERGY_MONTHLY_USAGE
WHERE DUM_MONTH = #{chgbillChargeMonth}
AND UNIT_ID = #{unitId}

SELECT INT_MAN_FEE_CD, INTG_FEE_AMOUNT
FROM INTEGRATED_MANAGEMENT_FEE
WHERE INTG_FEE_ID = #{chgbillChargeMonth}
AND UNIT_ID = #{unitId}
